19	package org.apache.pinot.segment.local.aggregator;
20	
21	import java.util.List;
22	import org.apache.datasketches.cpc.CpcSketch;
23	import org.apache.datasketches.cpc.CpcUnion;
24	import org.apache.pinot.common.request.context.ExpressionContext;
25	import org.apache.pinot.segment.local.utils.CustomSerDeUtils;
26	import org.apache.pinot.segment.spi.AggregationFunctionType;
27	import org.apache.pinot.spi.data.FieldSpec.DataType;
28	import org.apache.pinot.spi.utils.CommonConstants;
29	
30	
31	public class DistinctCountCPCSketchValueAggregator implements ValueAggregator<Object, CpcSketch> {
32	  public static final DataType AGGREGATED_VALUE_TYPE = DataType.BYTES;
33	
34	  private final int _lgK;
35	
36	  private int _maxByteSize;
37	
38	  public DistinctCountCPCSketchValueAggregator(List<ExpressionContext> arguments) {
39	    // length 1 means we use the Helix default
40	    if (arguments.size() <= 1) {
41	      _lgK = CommonConstants.Helix.DEFAULT_CPC_SKETCH_LGK;
42	    } else {
43	      _lgK = arguments.get(1).getLiteral().getIntValue();
44	    }
45	  }
46	
47	  @Override
48	  public AggregationFunctionType getAggregationType() {
49	    return AggregationFunctionType.DISTINCTCOUNTCPCSKETCH;
50	  }
51	
52	  @Override
53	  public DataType getAggregatedValueType() {
54	    return AGGREGATED_VALUE_TYPE;
55	  }
56	
57	  @Override
58	  public CpcSketch getInitialAggregatedValue(Object rawValue) {
59	    CpcSketch initialValue;
60	    if (rawValue instanceof byte[]) { // Serialized Sketch
61	      byte[] bytes = (byte[]) rawValue;
62	      initialValue = deserializeAggregatedValue(bytes);
63	      _maxByteSize = Math.max(_maxByteSize, bytes.length);
64	    } else if (rawValue instanceof byte[][]) { // Multiple Serialized Sketches
65	      byte[][] serializedSketches = (byte[][]) rawValue;
66	      CpcUnion union = new CpcUnion(_lgK);
67	      for (byte[] bytes : serializedSketches) {
68	        union.update(deserializeAggregatedValue(bytes));
69	      }
70	      initialValue = union.getResult();
71	      updateMaxByteSize(initialValue);
72	    } else {
73	      initialValue = empty();
74	      addObjectToSketch(rawValue, initialValue);
75	      updateMaxByteSize(initialValue);
76	    }
77	    return initialValue;
78	  }
79	
80	  @Override
81	  public CpcSketch applyRawValue(CpcSketch value, Object rawValue) {
82	    if (rawValue instanceof byte[]) {
83	      byte[] bytes = (byte[]) rawValue;
84	      CpcSketch sketch = union(value, deserializeAggregatedValue(bytes));
85	      updateMaxByteSize(sketch);
86	      return sketch;
87	    } else {
88	      addObjectToSketch(rawValue, value);
89	      updateMaxByteSize(value);
90	      return value;
91	    }
92	  }
93	
94	  @Override
95	  public CpcSketch applyAggregatedValue(CpcSketch value, CpcSketch aggregatedValue) {
96	    CpcSketch result = union(value, aggregatedValue);
97	    updateMaxByteSize(result);
98	    return result;
99	  }
100	
101	  @Override
102	  public CpcSketch cloneAggregatedValue(CpcSketch value) {
103	    return deserializeAggregatedValue(serializeAggregatedValue(value));
104	  }
105	
106	  @Override
107	  public int getMaxAggregatedValueByteSize() {
108	    // NOTE: For aggregated metrics, initial aggregated value might have not been generated. Returns the byte size
109	    //       based on lgK.
110	    return _maxByteSize > 0 ? _maxByteSize : CpcSketch.getMaxSerializedBytes(_lgK);
111	  }
112	
113	  @Override
114	  public byte[] serializeAggregatedValue(CpcSketch value) {
115	    return CustomSerDeUtils.DATA_SKETCH_CPC_SER_DE.serialize(value);
116	  }
117	
118	  @Override
119	  public CpcSketch deserializeAggregatedValue(byte[] bytes) {
120	    return CustomSerDeUtils.DATA_SKETCH_CPC_SER_DE.deserialize(bytes);
121	  }
122	
123	  private CpcSketch union(CpcSketch left, CpcSketch right) {
124	    if (left == null && right == null) {
125	      return empty();
126	    } else if (left == null) {
127	      return right;
128	    } else if (right == null) {
129	      return left;
130	    }
131	
132	    CpcUnion union = new CpcUnion(_lgK);
133	    union.update(left);
134	    union.update(right);
135	    return union.getResult();
136	  }
137	
138	  private void addObjectToSketch(Object rawValue, CpcSketch sketch) {
139	    if (rawValue instanceof String) {
140	      sketch.update((String) rawValue);
141	    } else if (rawValue instanceof Integer) {
142	      sketch.update((Integer) rawValue);
143	    } else if (rawValue instanceof Long) {
144	      sketch.update((Long) rawValue);
145	    } else if (rawValue instanceof Double) {
146	      sketch.update((Double) rawValue);
147	    } else if (rawValue instanceof Float) {
148	      sketch.update((Float) rawValue);
149	    } else if (rawValue instanceof Object[]) {
150	      addObjectsToSketch((Object[]) rawValue, sketch);
151	    } else {
152	      throw new IllegalStateException(
153	          "Unsupported data type for CPC Sketch aggregation: " + rawValue.getClass().getSimpleName());
154	    }
155	  }
156	
157	  private void addObjectsToSketch(Object[] rawValues, CpcSketch sketch) {
158	    if (rawValues instanceof String[]) {
159	      for (String s : (String[]) rawValues) {
160	        sketch.update(s);
161	      }
162	    } else if (rawValues instanceof Integer[]) {
163	      for (Integer i : (Integer[]) rawValues) {
164	        sketch.update(i);
165	      }
166	    } else if (rawValues instanceof Long[]) {
167	      for (Long l : (Long[]) rawValues) {
168	        sketch.update(l);
169	      }
170	    } else if (rawValues instanceof Double[]) {
171	      for (Double d : (Double[]) rawValues) {
172	        sketch.update(d);
173	      }
174	    } else if (rawValues instanceof Float[]) {
175	      for (Float f : (Float[]) rawValues) {
176	        sketch.update(f);
177	      }
178	    } else {
179	      throw new IllegalStateException(
180	          "Unsupported data type for CPC Sketch aggregation: " + rawValues.getClass().getSimpleName());
181	    }
182	  }
183	
184	  private void updateMaxByteSize(CpcSketch sketch) {
185	    if (sketch != null) {
186	      _maxByteSize = Math.max(_maxByteSize, sketch.toByteArray().length);
187	    }
188	  }
189	
190	  private CpcSketch empty() {
191	    return new CpcSketch(_lgK);
192	  }
193	}
