243	
244	    @Override
245	    public byte[] serialize(Sketch value) {
246	      // The serializer should respect existing ordering to enable "early stop"
247	      // optimisations on unions.
248	      if (!value.isCompact()) {
249	        return value.compact(value.isOrdered(), null).toByteArray();
250	      }
251	      return value.toByteArray();
252	    }
